def is_month_starting_on_weekend(year, month):
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    return wd(year, month, 1) in (5, 6)

def subtract_months_from_date(y, m, d, n_months):
    def is_leap(yr):
        return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
    total = (y * 12 + (m - 1)) - n_months
    ny = total // 12
    nm = total % 12 + 1
    dim = [31, 29 if is_leap(ny) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][nm - 1]
    nd = min(d, dim)
    return (ny, nm, nd)

