    for k, v in d2.items():
        res[k] = res.get(k, 0) + v
    return res

def is_valid_domain_name(s):
    labels = s.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not (1 <= len(label) <= 63):
            return False
        if label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    return labels[-1].isalpha() and len(labels[-1]) >= 2

def goldbach_pair(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            return (p, n - p)
    return None

def merge_keys_case_insensitive(d):
    result = {}
    for k, v in d.items():
        lk = k.lower()
        result[lk] = result.get(lk, 0) + v
    return result

def collatz_length(n):
    count = 1
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        count += 1
    return count

def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best = lst[:]
    for k in range(1, n):
        cand = lst[k:] + lst[:k]
        if cand < best:
            best = cand
    return best

def dedupe_keep_max(pairs):
    result = {}
    for name, score in pairs:
        if name not in result or score > result[name]:
            result[name] = score
    return result

def longest_strictly_increasing_prefix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            length += 1
        else:
            break
    return length

def key_with_min_value(d):
    best = min(d.values())
    cands = [k for k, v in d.items() if v == best]
    return min(cands)

def reverse_in_chunks(lst, k):
    out = []
    for i in range(0, len(lst), k):
        out.extend(reversed(lst[i:i+k]))
    return out

def pascal_to_snake(s):
    import re
    s1 = re.sub(r'(?<!^)(?=[A-Z])', '_', s)
    return s1.lower()

def find_missing_numbers(lst, lo, hi):
    present = set(lst)
    return [x for x in range(lo, hi + 1) if x not in present]

def largest_number_with_digit_sum(s, d):
    if s < 1 or s > 9 * d:
        return -1
    digits = [0] * d
    remaining = s
    for i in range(d):
        take = min(9, remaining)
        digits[i] = take
        remaining -= take
    return int(''.join(map(str, digits)))

def chunk_fixed_size_pad(lst, k, pad):
    chunks = [lst[i:i+k] for i in range(0, len(lst), k)]
    if chunks and len(chunks[-1]) < k:
        chunks[-1] = chunks[-1] + [pad] * (k - len(chunks[-1]))
    return chunks

def partition_odd_even(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def first_missing_positive(lst):
    s = set(lst)
    i = 1
    while i in s:
        i += 1
    return i

def recursive_dict_merge(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = recursive_dict_merge(result[k], v)
        else:
            result[k] = v
    return result

def bucket_count_by_width(nums, width, start):
    if not nums:
        return []
    max_v = max(nums)
    num_buckets = (max_v - start) // width + 1
    counts = [0] * num_buckets
    for v in nums:
        idx = (v - start) // width
        counts[idx] += 1
    return counts

def is_valid_mention(s):
    if len(s) < 2 or s[0] != '@':
        return False
    body = s[1:]
    if not (3 <= len(body) <= 16):
        return False
    if not body[0].isalpha():
        return False
    return all(c.isalnum() or c == '_' for c in body)

def is_numeric_palindrome(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def sort_by_manhattan_distance_from_point(points, target):
    tx, ty = target
    return sorted(points, key=lambda p: (abs(p[0]-tx)+abs(p[1]-ty), p[0], p[1]))

def value_occurrence_counts(d):
    counts = {}
    for v in d.values():
        counts[v] = counts.get(v, 0) + 1
    return counts

def rank_by_value_competition(d):
    ordered = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    result = {}
    prev_value = None
    prev_rank = 0
    for i, (k, v) in enumerate(ordered, start=1):
        if v != prev_value:
            rank = i
        else:
            rank = prev_rank
        result[k] = rank
        prev_value = v
        prev_rank = rank
    return result

def second_largest_with_duplicates(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[1]

def alternating_sum(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 2 == 0:
            total += x
        else:
            total -= x
    return total

def stable_unique_preserve_order(items):
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result
